package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTeDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("అల్లాహుమ్మా బీకా అస్బాహ్నా", "ఓ అల్లాహ్, మేము ఉదయం ప్రవేశిస్తాము మరియు సాయంత్రం ప్రవేశిస్తాము, మేము నీ ద్వారానే జీవిస్తాము మరియు నీ ద్వారానే మరణిస్తాము, మరియు నీకు పునరుత్థానం ఉంది.", "ఉదయం వేళ.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ ఉదయం మరియు సాయంత్రం సహచరులకు చెప్పమని నేర్పించారు."),
        "dua_allahumma_bika_amsayna" to DuaText("అల్లాహుమ్మా బీకా అమ్సేనా", "ఓ అల్లాహ్, మేము నీ ద్వారానే సాయంత్రం ప్రవేశిస్తాము మరియు నీ ద్వారానే ఉదయం ప్రవేశిస్తాము; నీ ద్వారానే మేము జీవిస్తాము మరియు నీ ద్వారానే మేము మరణిస్తాము, మరియు నీ వైపే తిరిగి రావడం.", "సాయంత్రం వేళ.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ ఉదయం మరియు సాయంత్రం సహచరులకు చెప్పమని నేర్పించారు."),
        "dua_afiyah_morning" to DuaText("అఫియా కోసం అడగడం", "ఓ అల్లాహ్, ఈ లోకంలో మరియు పరలోకంలో క్షమాపణ మరియు శ్రేయస్సు కోసం నేను నిన్ను అడుగుతున్నాను.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆని ఉదయం లేదా సాయంత్రం ఎన్నడూ విడిచిపెట్టలేదు.", "శ్రేయస్సు కంటే మెరుగైనది ఎవరికీ ఇవ్వబడలేదు."),
        "dua_afini_fi_badani" to DuaText("శరీరం, వినికిడి మరియు దృష్టి ఆరోగ్యం", "ఓ అల్లాహ్, నా శరీరానికి శ్రేయస్సు కలిగించు. ఓ అల్లాహ్, నా వినికిడికి శ్రేయస్సు కలిగించు. ఓ అల్లాహ్, నా దృష్టిని శ్రేయస్సు చేయుము. నీవు తప్ప దేవుడు లేడు.", "ప్రతి ఉదయం మరియు సాయంత్రం మూడు సార్లు.", "ఆరోగ్యం మరియు ఇంద్రియాల రక్షణ కోసం ఒక దుఆ."),
        "dua_ya_hayyu_aslih" to DuaText("నా వ్యవహారాలన్నింటినీ సరిదిద్దండి", "ఓ నిత్యజీవుడైన, ఓ సంరక్షకుడా, నీ దయతో నేను సహాయం కోరుతున్నానుః నా వ్యవహారాలన్నింటినీ సరిచేయండి మరియు నన్ను ఒక్క కన్ను చిమ్మేంత వరకు కూడా నాకు వదిలివేయవద్దు.", "ఉదయం సాయంత్రం ఇలా చెప్పమని ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఫాతిమా (ర) కు సలహా ఇచ్చారు.", "ప్రతి విషయంలో అల్లాహ్ సహాయం కోరండి."),
        "dua_subhanallah_adada_khalqihi" to DuaText("జువైరియాకు చెందిన తస్బియా (ఆర్ఏ)", "అల్లాహ్ మహిమగలవాడు మరియు అన్ని ప్రశంసలు ఆయనదే-ఆయన సృష్టి ఎంత, ఆయనకు నచ్చినంత, ఆయన సింహాసనం యొక్క బరువుకు మరియు ఆయన మాటల సిరాకు సమానం.", "ఉదయం మూడు సార్లు-గంటల ధిక్ర్ కంటే బరువుగా ఉంటుంది.", "ఈ నాలుగు పదబంధాలను మూడు సార్లు చెప్పడం తెల్లవారుజాము నుండి అర్ధరాత్రి వరకు ధిక్ర్ కంటే ఎక్కువ."),
        "dua_salawat" to DuaText("దురూద్-ఎ-ఇబ్రహీం", "ఓ అల్లాహ్, నీవు ఇబ్రహీం (అ) మరియు ఇబ్రహీం కుటుంబ సభ్యుల మీద ప్రార్థనలు పంపినప్పుడు ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం మరియు ముహమ్మద్ కుటుంబ సభ్యుల మీద ప్రార్థనలు పంపు. నీవు ప్రశంసనీయం, మహిమగలవాడవు. ఓ అల్లాహ్, ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం మరియు ముహమ్మద్ కుటుంబాన్ని ఆశీర్వదించు, నీవు ఇబ్రహీం (అ) మరియు ఇబ్రహీం కుటుంబాన్ని ఆశీర్వదించావు; నీవు ప్రశంసనీయం, మహిమగలవాడవు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ప్రార్థనలో మరియు అన్ని సమయాల్లో సలావత్.", "ఎవరికైనా ఒకసారి సలావత్ పంపితే, అల్లాహ్ అతనిపై పది దయ చూపిస్తాడు (ముస్లిం 408)."),
        "dua_wudu_after" to DuaText("వుడు తరువాత", "అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడటానికి హక్కు లేదని, ఒంటరిగా, భాగస్వామి లేకుండా, మరియు ముహమ్మద్ సల్లల్లాహు అలైహి వసల్లం అతని సేవకుడు మరియు ప్రవక్త అని నేను సాక్ష్యమిస్తున్నాను. ఓ అల్లాహ్, నన్ను పశ్చాత్తాపపడేవారిలో మరియు తమను తాము శుద్ధి చేసుకునేవారిలో ఒకరిగా చేసుకోండి.", "వుడు పూర్తి చేసిన తరువాత.", "అతను కోరుకున్న విధంగా ప్రవేశించడానికి స్వర్గం యొక్క ఎనిమిది ద్వారాలు తెరవబడతాయి."),
        "dua_wudu_before" to DuaText("వుడు ముందు", "అల్లాహ్ పేరిట.", "వుడు ప్రారంభించినప్పుడు.", "దాని మీద అల్లాహ్ పేరు ప్రస్తావించని వ్యక్తికి (పూర్తి) వుడు లేదు."),
        "dua_istiftah" to DuaText("ప్రారంభ ప్రార్థన (సనా)", "ఓ అల్లాహ్, నీకు మహిమ, నీకు స్తుతి. నీ పేరు ధన్యం, నీ మహిమ మహోన్నతమైనది, నీవు తప్ప దేవుడు లేడు.", "ప్రార్థన ప్రారంభంలో, ప్రారంభ తక్బీర్ తర్వాత.", "ప్రార్థన యొక్క సున్నహ్ ప్రారంభ దుఆ."),
        "dua_ruku" to DuaText("రుకులో", "మహిమగల నా ప్రభువుకు మహిమ కలగాలి.", "కనీసం మూడు సార్లు రుకులో.", "రుకు యొక్క సున్నహ్ తస్బిహ్."),
        "dua_sujood" to DuaText("సుజూద్ లో", "సర్వోన్నతుడైన నా ప్రభువుకు మహిమ కలగాలి.", "కనీసం మూడు సార్లు సుజూద్ లో.", "సాష్టాంగ నమస్కారం చేస్తున్నప్పుడు సేవకుడు తన ప్రభువుకు అత్యంత సన్నిహితుడు (ముస్లిం 482)."),
        "dua_rising_ruku" to DuaText("రుకు నుండి పైకి", "అల్లాహ్ తనను స్తుతించేవాడిని వింటాడు. మా ప్రభూ, సమస్త స్తుతులు నీకు చెందినవే.", "రుకు నుండి లేచి నిటారుగా నిలబడి ఉండగా.", "'రబ్బానా వా లకల్-హమ్ద్'అనే పదం దేవతలతో సమానంగా ఉంటే, అతని గత పాపాలు క్షమించబడతాయి."),
        "dua_between_sajdas" to DuaText("ఇద్దరు సజ్జదాస్ మధ్య", "నా ప్రభూ, నన్ను క్షమించు. నా ప్రభూ, నన్ను క్షమించు.", "రెండు సాష్టాంగ నమస్కారాల మధ్య కూర్చున్నప్పుడు.", "సాష్టాంగ నమస్కారాల మధ్య కూర్చోవడం యొక్క సున్నహ్ దుఆ."),
        "dua_before_salam_four" to DuaText("నాలుగు విషయాల నుండి శరణాగతి (సలాం ముందు)", "ఓ అల్లాహ్, నరకం శిక్ష నుండి, సమాధి శిక్ష నుండి, జీవితం మరియు మరణం యొక్క పరీక్షల నుండి మరియు తప్పుడు మెస్సీయ (దజ్జల్) యొక్క విచారణ యొక్క చెడు నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను.", "చివరి తాషహుద్ మరియు సలావత్ తరువాత, సలాం ముందు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ నాలుగు విషయాల నుండి ఆశ్రయం పొందాలని ఆదేశించాడు."),
        "dua_qunoot_witr" to DuaText("వితర్ లో కునూట్", "ఓ అల్లాహ్, నీవు మార్గనిర్దేశం చేసిన వారిలో నన్ను నడిపించు, నీవు నాకు శ్రేయస్సు ఇచ్చిన వారిలో నాకు శ్రేయస్సు ఇవ్వు, నీవు నీ సంరక్షణలో తీసుకున్న వారిలో నన్ను నీ సంరక్షణలో చేర్చుకో, నీవు ఇచ్చిన దానిలో నన్ను ఆశీర్వదించు, మరియు నీవు విధించిన దాని యొక్క చెడు నుండి నన్ను రక్షించు. నీవు తీర్పు ఇచ్చుచున్నావు, నీకు వ్యతిరేకంగా తీర్పు ఇవ్వడు, మరియు నీవు స్నేహం చేసినవాడు ఎన్నడూ అవమానించబడడు. మా ప్రభువైన నీవు ధన్యుడు, మహిమగలవాడవు.", "విదర్ ప్రార్థనలో-ప్రవక్త సయ్యద్ అలీహ్ వస్సల్మ్ దీనిని హసన్ ఇబ్న్ అలీ (ర.) కు బోధించారు.", "విదర్ యొక్క సున్నహ్ కునూత్. (హనాఫీలలో,'అల్లాహుమ్మా ఇన్నా నాస్తానుకా'కూడా బాగా ప్రసిద్ధి చెందింది.)"),
        "dua_qunoot_hanafi" to DuaText("కునూత్ (అల్లాహుమ్మా ఇన్నా నస్తానుకా)", "ఓ అల్లాహ్, మేము నీ సహాయం మరియు నీ క్షమాపణ కోరుతున్నాము, మేము నిన్ను విశ్వసిస్తున్నాము మరియు నీపై ఆధారపడ్డాము, మేము నిన్ను ఉత్తమ మార్గంలో స్తుతిస్తున్నాము, మేము నీకు కృతజ్ఞతలు తెలుపుతున్నాము మరియు కృతఘ్నులం కాదు, మరియు నిన్ను ధిక్కరించేవారిని మేము విడిచిపెట్టాము. ఓ అల్లాహ్, మేము నిన్ను మాత్రమే ఆరాధిస్తాము, నీకు నమస్కరిస్తాము మరియు సాష్టాంగ నమస్కారం చేస్తాము, మేము నీ వైపు త్వరపడి ప్రయత్నిస్తాము, మేము నీ దయను ఆశిస్తున్నాము మరియు నీ శిక్షకు భయపడతాము, ఖచ్చితంగా నీ శిక్ష అవిశ్వాసులకు చేరుతుంది.", "విటర్ లో-హనాఫీల అభ్యాసం.", "కునూట్లో ఉమర్ (ర) నుండి నివేదించబడింది."),
        "dua_sleep_aslamtu" to DuaText("నిద్రపోయే ముందు చివరి పదాలు", "ఓ అల్లాహ్, నేను నీకు లొంగిపోయాను, నా వ్యవహారాన్ని నీకు అప్పగించాను, నీపై ఆశతో, నీ పట్ల భయంతో నా రక్షణకు నా వీపును అప్పగించాను. నీకు తప్ప నీకు ఆశ్రయం లేదు, తప్పించుకునేది లేదు. నీవు అవతరింపజేసిన నీ గ్రంథాన్ని, నీవు పంపిన నీ ప్రవక్తను నేను విశ్వసిస్తున్నాను.", "వూడు తరువాత, కుడి వైపున పడుకోండి-నిద్రపోయే ముందు చివరి పదాలు.", "ఆ రాత్రి అతను మరణిస్తే, అతను ఫిత్రా (ఇస్లాం) రోజున మరణిస్తాడు."),
        "dua_waking_night" to DuaText("రాత్రివేళ మేల్కొనడం", "అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడటానికి హక్కు లేదు, ఒంటరిగా, భాగస్వామి లేకుండా. ఆధిపత్యం ఆయనదే, ప్రశంసలు ఆయనదే, అన్నింటిపై ఆయనకు అధికారం ఉంది. అన్ని ప్రశంసలు అల్లాహ్కు, మహిమ అల్లాహ్కు, అల్లాహ్ తప్ప ఎవరూ ఆరాధించబడటానికి హక్కు లేదు, అల్లాహ్ గొప్పవాడు, అల్లాహ్ వద్ద తప్ప శక్తి లేదా శక్తి లేదు. ఓ అల్లాహ్, నన్ను క్షమించు.", "రాత్రివేళ మేల్కొనేటప్పుడు.", "అతని దుఆకు సమాధానం ఇవ్వబడుతుంది, మరియు అతను వుడు చేసి ప్రార్థిస్తే, అతని ప్రార్థన ఆమోదించబడుతుంది."),
        "dua_hamm_ibn_masud" to DuaText("దుఃఖానికి దువా (ఇబ్న్ మసూద్)", "ఓ అల్లాహ్, నేను నీ సేవకుడిని, నీ సేవకుని కుమారుడిని, నీ దాసి కుమారుడిని. నా ముంజేయి నీ చేతిలో ఉంది, నాపై నీ ఆజ్ఞ అమలు చేయబడింది, నా గురించి నీ ఆజ్ఞ న్యాయమైనది. నేను నిన్ను ప్రతి పేరుతో అడుగుతున్నాను, దీనితో నీవు నిన్ను పేరు పెట్టుకున్నావు, లేదా నీ పుస్తకంలో వెల్లడి చేసుకున్నావు, లేదా నీ సృష్టిలో దేనికైనా బోధించావు, లేదా అదృశ్య జ్ఞానంలో నీతో ఉంచుకున్నాను-ఖురాన్ను నా హృదయానికి బుగ్గగా, నా ఛాతీకి వెలుగుగా, నా బాధను తొలగించడానికి, నా ఆందోళనను తొలగించడానికి.", "దుఃఖం మరియు బాధలో-అల్లాహ్ దుఃఖాన్ని ఆనందంతో భర్తీ చేస్తాడు.", "అల్లాహ్ అతని ఆందోళన మరియు దుఃఖాన్ని తొలగించి, దాని స్థానంలో అతనికి ఆనందాన్ని ఇస్తాడు."),
        "dua_difficulty_sahl" to DuaText("ఏదైనా కష్టంగా ఉన్నప్పుడు", "ఓ అల్లాహ్, మీరు సులభతరం చేసినవి తప్ప ఏదీ సులభం కాదు, మరియు మీరు కోరుకుంటే కష్టాన్ని సులభతరం చేస్తారు.", "ఏదైనా కష్టంగా అనిపించినప్పుడు.", "పరీక్షలలో సౌలభ్యం మరియు కష్టమైన పనులు."),
        "dua_musibah" to DuaText("అపాన్ ఎ క్యాలామిటీ (ఇస్తిర్జా)", "మేము అల్లాహ్కు చెందినవాళ్లం, ఆయన వైపే తిరిగి వస్తాము. అల్లాహ్వే, నా బాధలో నాకు ప్రతిఫలం ఇవ్వండి, దాని స్థానంలో నాకు మెరుగైనది ఏదైనా ఇవ్వండి.", "ఏదైనా నష్టం లేదా విపత్తు సంభవించినప్పుడు.", "అల్లాహ్ ఖచ్చితంగా మెరుగైనదాన్ని ఇస్తాడు-ఉమ్ సలమా (ర) ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇవ్వబడ్డాడు."),
        "dua_debt" to DuaText("రుణాల నుండి ఉపశమనం కోసం", "ఓ అల్లాహ్, నీవు నిషిద్ధం చేసినదానికి వ్యతిరేకంగా నీవు చట్టబద్ధం చేసిన దానితో నాకు సరిపోతుంది, మరియు నీ అనుగ్రహం ద్వారా నన్ను నీతో పాటు అన్నింటి నుండి స్వతంత్రంగా చేయండి.", "రుణాన్ని చెల్లించడానికి-అలీ (ఆర్ఏ) బోధించాడు.", "ఆ రుణం పర్వతంలా ఉన్నప్పటికీ, అల్లాహ్ దానిని పరిష్కరిస్తాడు."),
        "dua_anger" to DuaText("కోపంగా ఉన్నప్పుడు", "నేను శపించబడిన షైతాన్ నుండి అల్లాహ్ ఆశ్రయాన్ని కోరుతున్నాను.", "కోపంగా ఉన్నప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఇలా అన్నారుః అతను ఇలా చెబితే, అతని కోపం పోతుంది."),
        "dua_waswasa" to DuaText("విశ్వాసంలో వాసవాసాకు వ్యతిరేకంగా", "నేను అల్లాహ్ మరియు ఆయన దూతలను నమ్ముతాను.", "విశ్వాసం గురించి సాతాను గుసగుసలు వచ్చినప్పుడు.", "గుసగుసలు వచ్చినప్పుడు, ఇలా చెప్పి అక్కడే ఆగండి (అలాగే అల్లాహ్ లో ఆశ్రయం పొందండి)."),
        "dua_travel_full" to DuaText("పూర్తి ప్రయాణ అభ్యర్థన", "ఓ అల్లాహ్, ఈ ప్రయాణంలో మేము నిన్ను ధర్మాన్ని, భక్తిని, నిన్ను సంతోషపరిచే పనులను కోరుతున్నాము. ఓ అల్లాహ్, ఈ ప్రయాణాన్ని మాకు సులభతరం చేయి, దాని దూరాన్ని తగ్గించు. ఓ అల్లాహ్, నీవు ప్రయాణంలో సహచరుడవు, కుటుంబాన్ని కాపాడేవాడు.", "ప్రయాణానికి బయలుదేరినప్పుడు,'సుభానల్లధి సఖారా'తర్వాత.", "పూర్తి సున్నహ్ ప్రయాణ దుఆ."),
        "dua_return_travel" to DuaText("ప్రయాణం నుండి తిరిగి రావడం", "మనము తిరిగి వస్తాము, పశ్చాత్తాపపడుతున్నాము, మన ప్రభువును పూజిస్తున్నాము మరియు స్తుతిస్తున్నాము.", "ఒక ప్రయాణం నుండి తిరిగి వచ్చినప్పుడు.", "యాత్ర నుండి తిరిగి వచ్చినప్పుడు ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ విషయం చెప్పారు."),
        "dua_farewell_traveller" to DuaText("ఒక ప్రయాణికుడికి వీడ్కోలు", "నేను మీ మతాన్ని, మీ నమ్మకాన్ని, మీ చర్యల ఫలితాన్ని అల్లాహ్కు అప్పగిస్తున్నాను.", "ఒక ప్రయాణికుడికి వీడ్కోలు పలుకుతున్నప్పుడు.", "అల్లాహ్కు అప్పగించబడినది ఎన్నటికీ కోల్పోదు."),
        "dua_entering_town" to DuaText("ఒక చోట ఆగండి", "అల్లాహ్ సృష్టించిన అన్నిటి నుండి నేను పరిపూర్ణమైన మాటలలో ఆశ్రయం పొందుతాను.", "ఒక ప్రదేశంలో ఆగినప్పుడు లేదా కొత్త పట్టణానికి చేరుకున్నప్పుడు.", "అతను అక్కడి నుండి బయలుదేరే వరకు అతనికి ఏ హాని జరగదు."),
        "dua_boarding_ship" to DuaText("ఓడ/వాహనంలో ఎక్కడం", "దాని నౌకాయానం, లంగరు వేయడం అల్లాహ్నుబట్టి ఉంది. నిశ్చయంగా నా ప్రభువు క్షమాపణ ఇచ్చేవాడు, కరుణామయుడు.", "ఓడ లేదా వాహనంలో ఎక్కేటప్పుడు-ప్రవక్త నూహ్ (అ. స.) యొక్క పదాలు.", "ఖురాన్ పద్యం-నూహ్ (ఏఎస్) మందసము యొక్క దుఆ."),
        "dua_istighfar_hayyul_qayyum" to DuaText("హయుల్-ఖయ్యూమ్ తో ఇస్టిగ్ఫర్", "నేను అల్లాహ్ నుండి క్షమాపణ కోరుతున్నాను, ఆయన తప్ప ఏ దేవుడు, నిత్యజీవ, పోషకుడు లేడు, నేను పశ్చాత్తాపంతో ఆయన వైపు మొగ్గు చూపుతాను.", "పశ్చాత్తాపం కోసం.", "అతను యుద్ధభూమి నుండి పారిపోయినప్పటికీ అతని పాపాలు క్షమించబడతాయి."),
        "dua_rabbighfir_warham" to DuaText("రబ్బీగ్ఫీర్ వార్హామ్", "నా ప్రభూ, క్షమించి, కరుణ చూపించు, ఎందుకంటే నీవు దయ చూపించేవారిలో ఉత్తమమైనవాడివి.", "ఖురాన్ దుఆ-క్షమాపణ మరియు దయ కోసం.", "సూరహ్ అల్-ము'మినన్ యొక్క చివరి పద్యం."),
        "dua_majlis_kaffarah" to DuaText("కఫరత్ అల్-మజ్లిస్", "ఓ అల్లాహ్, నీకు మహిమ, నీకు స్తుతి. నీవు తప్ప దేవుడు లేడని నేను సాక్ష్యమిస్తున్నాను. నేను నీ క్షమాపణ కోరుతున్నాను, పశ్చాత్తాపంతో నీ వైపు తిరిగి వస్తాను.", "ఒక సమావేశం నుండి లేచినప్పుడు.", "ఇది సమావేశంలో చెప్పబడిన ఏ తప్పు కోసం క్షమాపణ అవుతుంది."),
        "dua_jami_forgiveness" to DuaText("సమగ్ర క్షమాపణ", "ఓ అల్లాహ్, నా తప్పులను, నా అజ్ఞానాన్ని, నా వ్యవహారాలలో నా మితిమీరిన పనిని, నాకంటే మీకు బాగా తెలిసిన అన్ని విషయాలను నాకు క్షమించండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క సమగ్ర దుఆ.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆ చేసేవారు."),
        "dua_parents_nuh" to DuaText("తల్లిదండ్రుల కోసం నూహ్ (ఏఎస్) యొక్క దువా", "నా ప్రభూ, నా తల్లిదండ్రులారా, విశ్వాసిగా నా ఇంట్లోకి ప్రవేశించే వారందరినీ, విశ్వాసులైన పురుషులు, స్త్రీలందరినీ క్షమించండి.", "ఒకరి తల్లిదండ్రుల కోసం మరియు విశ్వాసుల కోసం.", "ప్రవక్త నూహ్ (అ. స.) యొక్క దుఆ."),
        "dua_shukr_parents" to DuaText("తల్లిదండ్రులకు, నీతిమంతుడైన సంతానానికి కృతజ్ఞత", "నా ప్రభూ, నీవు నాకు, నా తల్లిదండ్రులకు ఇచ్చిన అనుగ్రహానికి కృతజ్ఞతతో ఉండటానికి, నీకు సంతోషాన్ని కలిగించే మంచి పనులు చేయడానికి, నా సంతానాన్ని నీతిమంతులుగా చేయడానికి నాకు వీలు కల్పించు. నేను పశ్చాత్తాపంతో నీ వైపు మొగ్గు చూపుతాను, నేను విధేయత చూపించేవారిలో ఒకడిని.", "నలభై సంవత్సరాల వయస్సుకు చేరుకున్న ఖురాన్ దుఆ.", "కృతజ్ఞత, మంచి పనులు మరియు ఒకరి పిల్లల నీతి-అన్నీ ఒకే దుఆలో ఉంటాయి."),
        "dua_intimacy" to DuaText("వైవాహిక సంబంధాలకు ముందు", "అల్లాహ్ పేరిట. ఓ అల్లాహ్, షైతాన్ను మాకు దూరంగా ఉంచండి మరియు మీరు మాకు (పిల్లలు) ఇచ్చిన దానికి షైతాన్ను దూరంగా ఉంచండి.", "వైవాహిక సంబంధాలకు ముందు.", "ఒక బిడ్డను తీర్పు ఇచ్చినట్లయితే, సైతాన్ దానిని ఎప్పటికీ హాని చేయదు."),
        "dua_ibrahim_children_protection" to DuaText("ఇల్లు మరియు పిల్లల రక్షణ", "నా ప్రభూ, ఈ నగరాన్ని భద్రపరచండి మరియు నన్ను మరియు నా పిల్లలను విగ్రహాలను పూజించకుండా దూరంగా ఉంచండి.", "ప్రవక్త ఇబ్రహీం (అ. స.) యొక్క దుఆ-నగరం మరియు అతని పిల్లల భద్రత కోసం.", "తౌహీద్ మీద దృఢంగా ఉండటానికి ఒక దుఆ."),
        "dua_drinking_milk" to DuaText("పాలు తాగుతున్నప్పుడు", "ఓ అల్లాహ్, మాకు అది అనుగ్రహించు మరియు మాకు మరింత ఇవ్వండి.", "పాలు తాగుతున్నప్పుడు.", "ఆహారం మరియు పానీయం రెండింటికీ పాలు సరిపోతాయి."),
        "dua_iftar_host" to DuaText("ఇతరులతో వేగంగా వ్యవహరించేటప్పుడు", "ఉపవాసం ఉన్నవారు మీతో వారి ఉపవాసాన్ని విరమించుకోవచ్చు, నీతిమంతులు మీ ఆహారాన్ని తినవచ్చు మరియు దేవదూతలు మీ కోసం ప్రార్థించవచ్చు.", "ఒకరి ఇంట్లో ఉపవాసం విరమించినప్పుడు.", "ఆతిథ్యమిచ్చేవారి కోసం ప్రవక్త యొక్క సలీం."),
    )
}
